    fun byName(name: String): ImageVector? {
        return when (name.toIconKey()) {
            "activity" -> Activity
            "archive" -> Archive
            "arrow-left" -> ArrowLeft
            "arrow-up-down" -> ArrowUpDown
            "ban" -> Ban
            "bell-ring" -> BellRing
            "bookmark" -> Bookmark
            "bot" -> Bot
            "bug" -> Bug
            "check" -> Check
            "chevron-down" -> ChevronDown
            "chevron-left" -> ChevronLeft
            "chevron-right" -> ChevronRight
            "circle" -> Circle
            "circle-arrow-up" -> CircleArrowUp
            "circle-check-big" -> CircleCheckBig
            "columns-3" -> Columns3
            "copy" -> Copy
            "download" -> Download
            "external-link" -> ExternalLink
            "eye" -> Eye
            "file-text" -> FileText
            "folder-open" -> FolderOpen
            "globe" -> Globe
            "hash" -> Hash
            "house" -> House
            "image" -> Image
            "image-plus" -> ImagePlus
            "inbox" -> Inbox
            "key" -> Key
            "layout-list" -> LayoutList
            "link" -> Link
            "list-todo" -> ListTodo
            "log-in" -> LogIn
            "log-out" -> LogOut
            "mail" -> Mail
            "message-square" -> MessageSquare
            "monitor" -> Monitor
            "paperclip" -> Paperclip
            "pencil" -> Pencil
            "play" -> Play
            "plus" -> Plus
            "refresh-cw" -> RefreshCw
            "search" -> Search
            "send" -> Send
            "settings" -> Settings
            "share-2" -> Share2
            "shield-check" -> ShieldCheck
            "smartphone" -> Smartphone
            "square" -> Square
            "square-check-big" -> SquareCheckBig
            "triangle-alert" -> TriangleAlert
            "trash" -> Trash
            "user" -> User
            "users" -> Users
            "x" -> X
            else -> null
        }
    }

    private fun String.toIconKey(): String {
        val normalized = trim()
        if (normalized.isEmpty()) {
            return normalized
        }
        return normalized
            .replace(Regex("([a-z0-9])([A-Z])"), "$1-$2")
            .replace('_', '-')
            .lowercase(Locale.US)
    }

